div.script:
function closeMobileAdhesionAd() {
    document.getElementById("mobile-adhesion").classList.add("closed");
}

function keyboardHandler(e) {
    var keycode = ( e.keyCode ? e.keyCode : e.which );
    if (keycode == "13") {
		closeMobileAdhesionAd();
	}
}

